#!/usr/bin/env python3
"""The datasets of the survey in one place, in the order of the dataset table and of the main table. Each group is one category of Sections 3 to 5. Fields: key used in the result files, name (the short name used in the main table and the figures), display (the full name with the abbreviation in bold, as the dataset table prints it, a vertical bar marks a line break), citation, data type, task, source of errors, metric, and the assessment section of the main table.
The full names follow the source of each dataset. EDM and DDPM: Wang et al. 2023. DCLM: Li et al. 2024. C4: the title of Dodge et al. 2021. Camelyon17: Litjens et al. 2018. COCO: the title of Lin et al. 2014. MIRFLICKR: the title of Huiskes and Lew 2008. NASA: the airfoil self-noise record of the UCI repository. KDD: the Readme of the table in the CleanML archive, which names KDD Cup 2014 as its source. USCensus and EEG: the dataset descriptions of CleanML.
The errors of the eleven tables with benchmark errors follow tables_summary.json, a type is listed when at least 0.5% of the records have it, syn. means a syntactic error, an out-of-domain value, and sem. a semantic error, an in-domain wrong value. The errors of the thirteen CleanML tables are the error types of the benchmark, for KDD those of its Readme. The data types follow the column types of the tables, Mixed means numerical and categorical columns together."""
REIN, UNI, CLEANML = "abdelaal2023rein", "ding2025uniclean", "li2021cleanml"
F1, R2, ACC = "Macro-F1", "$R^2$", "Accuracy"
def tab(key, name, cite, kind, task, errors, metric=F1, part="versions", display=None): return dict(key=key, name=name, display=display or name, cite=cite, type=kind, task=task, errors=errors, metric=metric, part=part)
def lab(key, name, kind, display=None): return tab(key, name, "northcutt2021pervasive", kind, "Classification", "Test labels", ACC, "protocol", display)
