   tab("flights", "Flights", UNI, "Cat.", "Classification", "Missing, syn., sem."), tab("hospitals", "Hospitals", UNI, "Cat.", "Classification", "Syn."), tab("smartfactory", "SmartFactory", REIN, "Num.", "Classification", "Missing"),
   tab("soccer_full", "Soccer", UNI, "Mixed", "Classification", "Syn., sem."), tab("bike", "Bike", REIN, "Num.", "Regression", "Syn., sem.", R2), tab("mercedes", "Mercedes", REIN, "Mixed", "Regression", "Missing, syn., sem.", R2),
