# what the experiments do, by the method families of Section 4, the count in the text is the length of this list
STRATEGIES = dict(rules=["data dictionary rules", "format, missing and duplicate scan", "text rules", "near-duplicate removal", "text rules with near-duplicate removal", "split overlap", "column pattern detector", "interquartile outlier detector", "three-sigma outlier detector", "dependency violation detector", "union of detectors"], sampling=["detector correction on a sample", "Wilson interval", "bootstrap interval", "stratified sample", "post-stratified estimate", "finite-population interval", "paired t test with multiple-comparison correction"], learned=["lowest perplexity", "middle perplexity", "highest perplexity", "CLIP similarity, top", "CLIP similarity, middle", "CLIP similarity, bottom", "CLIP consistency estimate", "published classifier filter", "cross-validated label errors", "fidelity on CLIP features", "Isolation Forest", "Raha", "Qwen table repair", "Qwen annotation", "Qwen corpus judge"], task=["repair by share", "delete by share", "repair by error type", "repair important columns first", "repair unimportant columns first", "replace by synthetic data", "extend by synthetic data", "random subset", "fine-class coverage", "choice by static score", "choice by task test", "best in hindsight", "factorial interaction", "split change", "out-of-distribution split", "window length", "independent runs", "relabel records before the fault onset", "drop records before the fault onset", "worst-group score", "score on a new test collection", "score on later months", "model size and token budget", "constructed mismatch", "training size", "CleanML imputation", "CleanML outlier detectors", "CleanML deduplication", "CleanML inconsistency repair"], human=["human labels", "crowd review of test labels", "documentation scoring", "documentation matched with data"])
